css:
.lsd-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.lsd-root,.lsd-root *,.lsd-root *::before,.lsd-root *::after{box-sizing:border-box}
.lsd-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.lsd-root img{display:block;border:0;max-width:none}
.lsd-root [hidden]{display:none!important}
.lsd-root .n33_1192{grid-column:1;align-content:stretch;display:flex;align-items:center;justify-content:space-between;margin-left:21px;margin-top:23.98px;position:relative;grid-row:1;width:213px}
.lsd-root .n33_1193{word-break:break-word;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:500;line-height:24px;font-style:normal;position:relative;flex-shrink:0;color:var(--wa-point, #98c4ff);font-size:20px;text-align:center;white-space:nowrap;width:79px}
.lsd-root .n33_1194{position:relative;flex-shrink:0;width:18px;height:18px}
.lsd-root .x91{position:absolute;display:block;inset:0;max-width:none;width:100%;height:100%}
.lsd-root [data-name="Widget/Sensor Status"] > * > *{margin-left:0;margin-top:0}
.lsd-root [data-node-id$=";13:354"]{border-image:linear-gradient(to bottom,var(--wa-line, #fff) 60%,var(--wa-point, #7cccff) 60%) 1}
.lsd-root[data-theme="light"]{background:var(--wa-bg, #eef2f7);color:var(--wa-text, #0e1a2b)}
.lsd-root[data-theme="light"] [data-name="Background"] > img{filter:invert(1) hue-rotate(180deg) saturate(0.4) brightness(1.05);opacity:0.5}
.lsd-root[data-theme="light"] [data-name="Building Image"] img{filter:saturate(0.92) brightness(0.98)}
.lsd-root[data-theme="light"] [data-name="Floor Plan"] img{filter:invert(1) hue-rotate(180deg) saturate(0.55) brightness(1.04)}
.lsd-root[data-theme="light"] [data-name^="Popup/"] > [data-name="Background"]::after{content:"";position:absolute;inset:0;border-radius:inherit;background:color-mix(in srgb, var(--wa-bg, rgb(247 250 254)) 92%, transparent);pointer-events:none}
